#include<bits/stdc++.h>
using namespace std;

int main(){
	// 入力を受け取る
	int n,k;
	cin >> n >> k;
	vector<int>a(n);
	for(int i=0;i<n;i++)cin >> a[i];

	//出力
	if(k>=n){
		for(int i=0;i<n;i++)cout << 0 << ' ';
	}else{
		for(int i=0;i<n-k;i++)cout << a[k+i] << ' ';
		for(int i=0;i<k;i++)cout << 0 << ' ';
	}

}
